/**
 * Returns true if the message should be printed in the given timestamp, otherwise returns false. If this method returns false, the message will not be printed. The timestamp is in seconds granularity.
 */
public boolean shouldPrintMessage(int timestamp, String message){
    // Store the timestamp along with the message in a hash map
    // If the message is not in the map, add it and return true
    // If the message is in the map, check the timestamp and return false if too recent, otherwise update the timestamp and return true
    long ttl = 10; // Time to live in seconds
    Map<String, Long> messageTimestamps = new ConcurrentHashMap<>();

    if (messageTimestamps.containsKey(message)) {
        long lastTimestamp = messageTimestamps.get(message);
        if ((timestamp - lastTimestamp) < ttl) {
            return false;
        } else {
            messageTimestamps.put(message, timestamp);
        }
    } else {
        messageTimestamps.put(message, timestamp);
    }

    return true;
}
