public String format(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }

    // Assuming a simple conversion pattern for demonstration
    String conversionPattern = "%d %p %c - %m%n";
    StringBuilder formattedString = new StringBuilder();

    for (char c : conversionPattern.toCharArray()) {
        if (c == '%') {
            int nextIndex = conversionPattern.indexOf(' ', 1);
            String formatCode = conversionPattern.substring(1, nextIndex);
            conversionPattern = conversionPattern.substring(nextIndex + 1);

            if ("d".equals(formatCode)) {
                formattedString.append(event.getTimeStamp());
            } else if ("p".equals(formatCode)) {
                formattedString.append(event.getLevel());
            } else if ("c".equals(formatCode)) {
                formattedString.append(event.getLoggerName());
            } else if ("m".equals(formatCode)) {
                formattedString.append(event.getMessage());
            } else if ("%n".equals(formatCode)) {
                formattedString.append(System.lineSeparator());
            } else {
                formattedString.append('%').append(c);
            }
        } else {
            formattedString.append(c);
        }
    }

    return formattedString.toString();
}
