private int parseEndOfLine(String headerPart, int end) {
    // Ensure that the end index is within the bounds of the headerPart
    if (end >= headerPart.length()) {
        throw new IllegalArgumentException("End index is out of bounds");
    }

    // Iterate from the end index backwards to find the \r\n sequence
    for (int i = end; i > 0; i--) {
        if (headerPart.charAt(i) == '\n' && headerPart.charAt(i - 1) == '\r') {
            return i - 1;
        }
    }

    // If \r\n sequence is not found, throw an exception
    throw new IllegalArgumentException("End-of-line sequence not found");
}
