    if (headerPart == null || headerPart.isEmpty()) {
        throw new IllegalArgumentException("Header part must not be null or empty");
    }

    // Check if the end index is within the valid range
    if (end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("End index must be within the valid range of the header part");
    }

    // Iterate through the characters from the end index to the beginning
    for (int i = end; i > 0; i--) {
        char currentChar = headerPart.charAt(i);
        char previousChar = headerPart.charAt(i - 1);

        // Check if the current character and the previous character form a "\r\n" sequence
        if (currentChar == '\n' && previousChar == '\r') {
            return i - 1; // Return the index of the '\r' character
        }
    }

    // If no "\r\n" sequence is found, return -1 to indicate that the end of the line was not found
    return -1;
}
