public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    if (resultMap == null || resultMap.isEmpty()) {
        throw new IllegalArgumentException("Result map cannot be null or empty");
    }

    // Clear existing graph
    target.removeAllVertices();
    target.removeAllEdges();

    // Get a list of unique node labels from the result map
    List<String> nodeLabels = new ArrayList<>(resultMap.keySet());
    Collections.sort(nodeLabels);

    int numVertices = nodeLabels.size();
    int numPartitions = (int) Math.sqrt(numVertices) + 1;

    // Create partitions
    List<Set<String>> partitions = new ArrayList<>();
    for (int i = 0; i < numPartitions; i++) {
        partitions.add(new HashSet<>());
    }

    // Distribute nodes among partitions
    for (String label : nodeLabels) {
        partitions.get(label.hashCode() % numPartitions).add(label);
    }

    // Create vertices in the target graph
    Map<String, V> vertexMap = new HashMap<>();
    for (String label : nodeLabels) {
        V vertex = resultMap.get(label);
        vertexMap.put(label, vertex);
        target.addVertex(vertex);
    }

    // Create edges between partitions
    for (int i = 0; i < partitions.size(); i++) {
        Set<String> partitionA = partitions.get(i);
        for (int j = i + 1; j < partitions.size(); j++) {
            Set<String> partitionB = partitions.get(j);
            for (String labelA : partitionA) {
                for (String labelB : partitionB) {
                    E edge = target.addEdge(vertexMap.get(labelA), vertexMap.get(labelB));
                    if (edge == null) {
                        throw new IllegalArgumentException("Failed to create edge between " + labelA + " and " + labelB);
                    }
                }
            }
        }
    }
}
