public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Parameters cannot be null");
    }

    try {
        // Convert the message to bytes using the provided schema
        byte[] data = schema.toByteArray(message);

        // Get the size of the message
        int size = data.length;

        // Ensure the buffer has enough space to write the size and the message
        if (buffer.available() < size + 4) {
            buffer = LinkedBuffer.allocate(LinkedBuffer.MIN_BUFFER_SIZE);
        }

        // Write the size of the message
        buffer.put(size >>> 24);
        buffer.put((size >>> 16) & 0xFF);
        buffer.put((size >>> 8) & 0xFF);
        buffer.put(size & 0xFF);

        // Write the message to the buffer
        buffer.put(data);

        // Write the buffer contents to the output stream
        out.write(buffer.array(), 0, buffer.length());
        out.flush();

        // Return the size of the message
        return size;
    } catch (IOException e) {
        throw e;
    } catch (Exception e) {
        throw new IOException("Error serializing message", e);
    }
}
