public static void createConfigurationDirectory() {
    String userHome = System.getProperty("user.home");
    String lf5Path;

    if (isWindows2000()) {
        lf5Path = userHome + File.separator + "Documents and Settings" + File.separator + "lf5";
    } else {
        lf5Path = userHome + File.separator + "lf5";
    }

    File lf5Dir = new File(lf5Path);

    if (!lf5Dir.exists()) {
        try {
            boolean created = lf5Dir.mkdirs();
            if (!created) {
                throw new IOException("Failed to create directory: " + lf5Path);
            }
        } catch (SecurityException e) {
            throw new IllegalArgumentException("Access to directory creation is denied: " + lf5Path, e);
        } catch (Exception e) {
            throw new RuntimeException("An unexpected error occurred while creating the directory: " + lf5Path, e);
        }
    }
}

private static boolean isWindows2000() {
    return System.getProperty("os.name").startsWith("Windows 2000");
}
