        // Handle potential overflow or division by zero
        throw new IllegalArgumentException("Invalid time bucket or dayStep", e);
    } catch (Exception e) {
        // Handle other unexpected exceptions
        throw new RuntimeException("Error compressing time bucket", e);
    }
}

