        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid index or length");
    }

    int utf8Size = 0;
    int endIndex = Math.min(index + len, str.length());
    for (int i = index; i < endIndex; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            utf8Size++; // 1 byte for single-byte characters
        } else if (ch <= 0x7FF) {
            utf8Size += 2; // 2 bytes for two-byte characters
        } else if (ch <= 0xFFFF) {
            utf8Size += 3; // 3 bytes for three-byte characters
        } else {
            utf8Size += 4; // 4 bytes for four-byte characters
        }
    }
    return utf8Size;
}
