public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new NullPointerException("Write session cannot be null");
    }
    if (lb == null) {
        throw new NullPointerException("LinkedBuffer cannot be null");
    }

    try {
        byte[] bytes = str.toString().getBytes("UTF-8");
        if (lb.hasRemaining(bytes.length)) {
            lb.put(bytes);
        } else {
            lb = session.grow(lb, bytes.length);
            lb.put(bytes);
        }
        return lb;
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding is not supported", e);
    }
}
