private static String performVariableSubstitution(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int index = 0;

    while (index < value.length()) {
        if (value.charAt(index) == '${') {
            int endIndex = value.indexOf('}', index);
            if (endIndex == -1) {
                // Invalid variable format, append the rest of the string as is
                result.append(value.substring(index));
                break;
            }

            String variable = value.substring(index + 2, endIndex);
            String replacement = props.getProperty(variable);
            if (replacement != null) {
                result.append(replacement);
            } else {
                // Variable not found, append the variable as is
                result.append('${').append(variable).append('}');
            }

            index = endIndex + 1;
        } else {
            result.append(value.charAt(index++));
        }
    }

    return result.toString();
