import java.io.UnsupportedEncodingException;
import java.net.URI;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    String path = u.getPath();
    if (path == null) {
        return Arrays.asList();
    }

    // Remove leading '/' if present
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    List<String> pathSegments = Arrays.asList(path.split("/"));

    if (!decode) {
        return pathSegments.stream()
                .map(segment -> new PathSegmentImpl(segment))
                .collect(Collectors.toList());
    }

    List<PathSegmentImpl> decodedSegments = new ArrayList<>();
    for (String segment : pathSegments) {
        try {
            String decodedSegment = URLDecoder.decode(segment, StandardCharsets.UTF_8.toString());
            decodedSegments.add(new PathSegmentImpl(decodedSegment));
        } catch (UnsupportedEncodingException e) {
            // Should never happen with UTF-8
            throw new RuntimeException("UTF-8 encoding not supported", e);
        }
    }

    return decodedSegments;
}
