    return true;
}

private static int findClosestPrime(int num) {
    int lower = num - num / 10;
    int upper = num + num / 10;

    while (lower >= 2) {
        if (isPrime(lower)) {
            return lower;
        }
        lower--;
    }

    while (upper < Integer.MAX_VALUE) {
        if (isPrime(upper)) {
            return upper;
        }
        upper++;
    }

    throw new IllegalStateException("No prime number found within the valid range");
