    int totalLength = 0;
    for (ByteBuffer buffer : buffers) {
        totalLength += buffer.remaining();
    }

    // Create a byte array to hold the combined data
    byte[] byteArray = new byte[totalLength];

    // Copy data from each buffer into the byte array
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        int length = buffer.remaining();
        buffer.get(byteArray, offset, length);
        offset += length;
    }

    return byteArray;
}
