    int removedCount = 0;
    for (Iterator<CategoryNode> it = node.getChildren().iterator(); it.hasNext();) {
        CategoryNode child = it.next();
        if (!child.isActive()) {
            it.remove();
            removedCount++;
        } else {
            removedCount += removeInactiveNodes(child);
