        return 0;
    }

    int removedCount = 0;

    // Recursively remove unused nodes from the left subtree
    if (root.left != null) {
        int leftRemoved = removeUnusedNodes(root.left);
        if (leftRemoved == 1 && !root.left.isActive()) {
            root.left = null;
            removedCount = 1;
        } else {
            removedCount += leftRemoved;
        }
    }

    // Recursively remove unused nodes from the right subtree
    if (root.right != null) {
        int rightRemoved = removeUnusedNodes(root.right);
        if (rightRemoved == 1 && !root.right.isActive()) {
            root.right = null;
            removedCount += 1;
        } else {
            removedCount += rightRemoved;
