public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check for null input and non-positive byteLength
    if (byteArrayValue == null && byteLength != 0) {
        throw new IllegalArgumentException("byteArrayValue must be non-null if byteLength is non-zero");
    }
    if (byteOffset < 0 || byteLength < 0 || byteOffset > byteArrayValue.length - byteLength) {
        throw new IllegalArgumentException("Invalid byteOffset or byteLength");
    }

    // Calculate the new length required
    int newLength = this.length + byteLength;

    // Ensure the buffer is large enough
    if (newLength > this.storage.length) {
        growBuffer(newLength);
    }

    // Copy the byte array into the storage
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, this.storage, this.length, byteLength);
    } else {
        // Fill with null bytes if byteArrayValue is null
        for (int i = 0; i < byteLength; i++) {
            this.storage[this.length + i] = 0;
        }
    }

    // Update the length
    this.length = newLength;

    return this;
}

// Helper method to grow the buffer
private void growBuffer(int newLength) {
    byte[] newStorage = new byte[Math.max(newLength, this.storage.length * 2)];
    System.arraycopy(this.storage, 0, newStorage, 0, this.length);
    this.storage = newStorage;
}
