private GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input set and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);

    if (edgeList.isEmpty()) {
        return graph.createPath(null);
    }

    E firstEdge = edgeList.get(0);
    E lastEdge = edgeList.get(edgeList.size() - 1);

    if (!Objects.equals(graph.getEdgeSource(firstEdge), graph.getEdgeTarget(lastEdge))) {
        throw new IllegalArgumentException("Input set does not form a valid tour");
    }

    GraphPath<V, E> path = graph.createPath(graph.getEdgeSource(firstEdge));

    for (E edge : edgeList) {
        path = path.extend(graph.getEdgeTarget(edge));
    }

    return path;
}
