protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    Iterator<E> iterator = tour.iterator();
    if (!iterator.hasNext()) {
        return graph.createGraphPath(); // or return null, depending on the design
    }

    V startVertex = iterator.next();
    V currentNode = startVertex;
    GraphPath.Builder<V,E> pathBuilder = new GraphPath.Builder<>(startVertex, startVertex, 0);

    while (iterator.hasNext()) {
        E edge = iterator.next();
        V endVertex = graph.getEdgeTarget(edge);

        pathBuilder = pathBuilder.addEdge(edge, graph.getEdgeWeight(edge), endVertex);
        currentNode = endVertex;
    }

    // Add the edge from the last vertex to the start vertex (assuming graph is cyclic)
    E returnEdge = graph.findEdge(currentNode, startVertex);
    if (returnEdge != null) {
        pathBuilder = pathBuilder.addEdge(returnEdge, graph.getEdgeWeight(returnEdge), startVertex);
    } else {
        throw new NoSuchElementException("Graph is not cyclic or does not contain a path back to the start vertex");
    }

    return pathBuilder.create();
}

