protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null; // Return null for empty or null input
    }

    List<Edge<V, E>> edgeList = new ArrayList<>(tour);

    if (edgeList.size() < 2) {
        return new DefaultGraphPath<>(graph, edgeList, GraphPath.PathKind.UNDIRECTED); // Single edge or isolated vertex
    }

    // Check if the tour forms a valid path in the graph
    V startVertex = edgeList.get(0).getEndpoints().getFirst();
    V endVertex = edgeList.get(edgeList.size() - 1).getEndpoints().getSecond();

    if (!graph.containsVertex(startVertex) || !graph.containsVertex(endVertex)) {
        throw new IllegalArgumentException("Graph does not contain all vertices in the tour");
    }

    for (int i = 0; i < edgeList.size() - 1; i++) {
        Edge<V, E> currentEdge = edgeList.get(i);
        Edge<V, E> nextEdge = edgeList.get(i + 1);
        V currentVertex = currentEdge.getEndpoints().getSecond();
        V nextVertex = nextEdge.getEndpoints().getFirst();

        if (!currentEdge.getEndpoints().getSecond().equals(nextEdge.getEndpoints().getFirst())) {
            throw new IllegalArgumentException("Edges in the tour do not form a valid path");
        }
    }

    return new DefaultGraphPath<>(graph, edgeList, GraphPath.PathKind.UNDIRECTED);
}
