public List<SequenceRange> buildSequenceRanges() {
    // Step 1: Define a list to hold the sequence ranges
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Step 2: Retrieve current profiles segment snapshots
    List<ProfileSegmentSnapshot> snapshots = getCurrentProfilesSegmentSnapshots();

    // Step 3: Check if snapshots are not null and not empty
    if (snapshots == null || snapshots.isEmpty()) {
        return sequenceRanges; // Return empty list if no snapshots
    }

    // Step 4: Sort snapshots by their start index to ensure correct sequence
    snapshots.sort((s1, s2) -> Integer.compare(s1.getStartIndex(), s2.getStartIndex()));

    // Step 5: Initialize the first range with the first snapshot
    SequenceRange currentRange = new SequenceRange(snapshots.get(0).getStartIndex(), snapshots.get(0).getEndIndex());

    // Step 6: Iterate through the sorted snapshots and build sequence ranges
    for (int i = 1; i < snapshots.size(); i++) {
        ProfileSegmentSnapshot snapshot = snapshots.get(i);
        int currentStart = currentRange.getStartIndex();
        int currentEnd = currentRange.getEndIndex();
        int snapshotStart = snapshot.getStartIndex();
        int snapshotEnd = snapshot.getEndIndex();

        // Step 7: Check if the current snapshot overlaps with the current range
        if (snapshotStart <= currentEnd) {
            // If overlapping, extend the current range to the end of the current snapshot
            currentRange.setEndIndex(Math.max(currentEnd, snapshotEnd));
        } else {
            // If not overlapping, add the current range to the list and start a new range
            sequenceRanges.add(currentRange);
            currentRange = new SequenceRange(snapshotStart, snapshotEnd);
        }
    }

    // Step 8: Add the last range to the list
    sequenceRanges.add(currentRange);

    // Step 9: Return the list of sequence ranges
    return sequenceRanges;
}
```

