public List<SequenceRange> buildSequenceRanges() throws IllegalStateException {
    // Step 1: Check if current profiles are available
    if (profiles == null || profiles.isEmpty()) {
        throw new IllegalStateException("No profiles available to build sequence ranges.");
    }

    // Step 2: Initialize a list to store sequence ranges
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Step 3: Iterate through each profile to build sequence ranges
    for (Profile profile : profiles) {
        // Step 3.1: Extract sequence data from the profile
        List<Long> sequences = profile.getSequences();
        if (sequences == null || sequences.isEmpty()) {
            continue; // Skip profiles without sequences
        }

        // Step 3.2: Sort the sequence data
        Collections.sort(sequences);

        // Step 3.3: Build sequence ranges
        for (int i = 0; i < sequences.size() - 1; i++) {
            long start = sequences.get(i);
            long end = sequences.get(i + 1);
            sequenceRanges.add(new SequenceRange(start, end));
        }
    }

    // Step 4: Return the list of sequence ranges
    return sequenceRanges;
}
