public List<SequenceRange> buildSequenceRanges() {
    // Step 1: Define the input parameters and the output list
    List<Profile> currentProfiles = getCurrentProfiles(); // Assume this method gets the current profiles
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Step 2: Validate the input
    if (currentProfiles == null || currentProfiles.isEmpty()) {
        return sequenceRanges; // Return an empty list if no profiles are found
    }

    // Step 3: Build the sequence ranges
    for (Profile profile : currentProfiles) {
        try {
            // Step 4: Get the segments and sort them
            List<Segment> segments = profile.getSegments(); // Assume this method gets the segments for a profile
            Collections.sort(segments, Comparator.comparingInt(Segment::getStart));

            // Step 5: Merge overlapping segments
            List<Segment> mergedSegments = mergeSegments(segments);

            // Step 6: Convert segments to sequence ranges
            for (Segment segment : mergedSegments) {
                SequenceRange range = new SequenceRange(segment.getStart(), segment.getEnd());
                sequenceRanges.add(range);
            }
        } catch (Exception e) {
            // Step 7: Handle any unexpected exceptions
            e.printStackTrace(); // In a real scenario, log the exception properly
        }
    }

    return sequenceRanges;
}

private List<Segment> mergeSegments(List<Segment> segments) {
    List<Segment> mergedSegments = new ArrayList<>();
    if (segments == null || segments.isEmpty()) {
        return mergedSegments;
    }

    Collections.sort(segments, Comparator.comparingInt(Segment::getStart));
    Segment current = segments.get(0);

    for (int i = 1; i < segments.size(); i++) {
        Segment next = segments.get(i);
        if (current.getEnd() >= next.getStart()) {
            current.setEnd(Math.max(current.getEnd(), next.getEnd()));
        } else {
            mergedSegments.add(current);
            current = next;
        }
    }

    mergedSegments.add(current);
    return mergedSegments;
}
