// Helper method to ensure the byte vector has enough capacity
private void ensureCapacity(int additionalCapacity) {
    if (this.size + additionalCapacity > this.capacity) {
        int newSize = Math.max(this.size + additionalCapacity, this.capacity * 2);
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(this.buffer, 0, newBuffer, 0, this.size);
        this.buffer = newBuffer;
        this.capacity = newSize;
    }
}

// Helper method to add a byte to the byte vector
private void add(byte b) {
    if (this.size >= this.capacity) {
        ensureCapacity(1);
    }
    this.buffer[this.size++] = b;
