public static String applyRelativePath(String path, String relativePath) {
    try {
        // Split the path into parts
        String[] pathParts = path.split("/");
        String[] relativeParts = relativePath.split("/");

        // Remove the last part of the path to start building the new path
        if (pathParts.length > 0) {
            pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
        }

        // Append the relative path parts to the new path
        for (String part : relativeParts) {
            if ("..".equals(part)) {
                // Go up one directory
                if (pathParts.length > 0) {
                    pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
                }
            } else if (!"".equals(part)) {
                // Append the part to the new path
                pathParts = Arrays.copyOf(pathParts, pathParts.length + 1);
                pathParts[pathParts.length - 1] = part;
            }
        }

        // Join the parts to form the new path
        return String.join("/", pathParts);
    } catch (Exception e) {
        // Handle any potential exceptions and return an empty string or rethrow
        System.err.println("Error applying relative path: " + e.getMessage());
        return "";
    }
}
