                int threadID = Integer.parseInt(parts[1]);
                String threadName = parts[2];
                String stackTrace = parts[3];

                boolean withinRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (timestamp.after(range.getStartTime()) && timestamp.before(range.getEndTime())) {
                        withinRange = true;
                        break;
                    }
                }

                if (withinRange) {
                    threadSnapshots.add(new ThreadSnapshot(timestamp, threadID, threadName, stackTrace));
                }
            } catch (NumberFormatException e) {
                continue; // Skip lines with invalid numeric values
