public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || file.isDirectory() || timeRanges == null) {
        throw new IllegalArgumentException("Invalid input: file and timeRanges must not be null and file must exist and not be a directory");
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Assuming the file format is a simple text format where each line represents a snapshot
            // Each snapshot line should contain time information followed by snapshot details
            String[] parts = line.split(" ");
            if (parts.length < 2) {
                continue; // Skip lines that do not have enough information
            }

            long timestamp = Long.parseLong(parts[0]); // Assuming the first part is the timestamp
            String snapshotDetails = String.join(" ", Arrays.copyOfRange(parts, 1, parts.length));

            // Check if the timestamp falls within any of the specified time ranges
            boolean withinRange = timeRanges.stream()
                    .anyMatch(range -> timestamp >= range.getStartTime() && timestamp <= range.getEndTime());

            if (withinRange) {
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, snapshotDetails);
                snapshots.add(snapshot);
            }
        }
    } catch (NumberFormatException e) {
        throw new IOException("Invalid file format: expected number format for timestamp", e);
    }

    return snapshots;
}
